"""
Spanish vocabulary for the ad-block overlay.

1291 words and phrases, 5062 example sentences. Each entry is
    (spanish, pronunciation, english, (example, example, ...))
Pronunciation: simplified phonetics, the stressed syllable in CAPITALS.
Each showing picks two of an entry's examples at random, and vocab_picker's
shuffle bag shows every entry once before any repeats.

Spelling is real Spanish (accents, ñ, ¿ ¡). The overlay sends it Latin-1,
which is what ustreamer's byte-per-glyph renderer draws correctly
(vocab_picker.latin1_safe). Keep examples at most 48 characters: overlay
lines don't wrap.

Built 2026-10-18 from the original 776 entries (accents restored, wrong-word
examples dropped, duplicates merged, 3 new examples each) plus ~600 new
entries; see git history for the old list.
"""

